/**
 * YouTube caption reader.
 *
 * Talking videos (podcasts, interviews, lectures) already carry a timed,
 * word-accurate transcript on YouTube — either uploaded by the creator or
 * generated by YouTube's own speech recognition. Reading it costs one plain web
 * request and zero AI tokens, so a two-hour podcast can be mined in seconds
 * instead of being watched frame by frame.
 *
 * Captions never say WHO is speaking (see transcript-mine.server.ts for that);
 * this file only answers "what was said, and exactly when".
 */
import type { Cue } from "@/lib/timeline.server";

const UA =
  "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36";

export type CaptionTrack = {
  baseUrl: string;
  languageCode: string;
  /** "asr" when YouTube generated it by listening; empty when a human uploaded it. */
  kind: string;
  name: string;
};

type PlayerCaptions = {
  captions?: {
    playerCaptionsTracklistRenderer?: {
      captionTracks?: { baseUrl?: string; languageCode?: string; kind?: string; name?: { simpleText?: string } }[];
    };
  };
};

/**
 * YouTube serves its normal website clients an "unavailable" page to server
 * addresses, and those replies carry no captions. The player clients below are
 * the ones that still answer honestly from a datacenter, so they are the ones
 * asked. Verified live against real videos.
 */
const PLAYER_CLIENTS = {
  vr: {
    ua: "com.google.android.apps.youtube.vr.oculus/1.60.19 (Linux; U; Android 12; GB) gzip",
    client: {
      clientName: "ANDROID_VR",
      clientVersion: "1.60.19",
      deviceModel: "Quest 3",
      androidSdkVersion: 32,
      osName: "Android",
      osVersion: "12",
      hl: "en",
      gl: "US",
    },
  },
  ios: {
    ua: "com.google.ios.youtube/20.10.4 (iPhone16,2; U; CPU iOS 18_3_2 like Mac OS X)",
    client: {
      clientName: "IOS",
      clientVersion: "20.10.4",
      deviceMake: "Apple",
      deviceModel: "iPhone16,2",
      osName: "iPhone",
      osVersion: "18.3.2.22D82",
      hl: "en",
      gl: "US",
    },
  },
} as const;

const PLAYER_URL =
  "https://www.youtube.com/youtubei/v1/player?key=AIzaSyAO_FJ2SlqU8Q4STEHLGCilw_Y9_11qcW8";

async function playerResponse(videoId: string, client: keyof typeof PLAYER_CLIENTS): Promise<PlayerCaptions | null> {
  try {
    const pick = PLAYER_CLIENTS[client];
    const res = await fetch(PLAYER_URL, {
      method: "POST",
      headers: { "Content-Type": "application/json", "User-Agent": pick.ua },
      body: JSON.stringify({ videoId, contentCheckOk: true, racyCheckOk: true, context: { client: pick.client } }),
    });
    if (!res.ok) return null;
    return (await res.json()) as PlayerCaptions;
  } catch {
    return null;
  }
}

/** Every caption track YouTube exposes for a video, human-made ones first. */
export async function listCaptionTracks(videoId: string): Promise<CaptionTrack[]> {
  for (const client of ["vr", "ios"] as const) {
    const body = await playerResponse(videoId, client);
    const raw = body?.captions?.playerCaptionsTracklistRenderer?.captionTracks ?? [];
    const tracks = raw
      .filter((t) => t.baseUrl)
      .map<CaptionTrack>((t) => ({
        baseUrl: t.baseUrl!,
        languageCode: t.languageCode ?? "",
        kind: t.kind ?? "",
        name: t.name?.simpleText ?? "",
      }));
    if (tracks.length) {
      // A transcript a person typed is punctuated and often names the speakers,
      // so it always beats the machine-listened one.
      return tracks.sort((a, b) => Number(a.kind === "asr") - Number(b.kind === "asr"));
    }
  }
  return [];
}

type Json3 = { events?: { tStartMs?: number; dDurationMs?: number; segs?: { utf8?: string }[] }[] };

function cleanLine(text: string): string {
  return text
    .replace(/\s+/g, " ")
    .replace(/^\[[^\]]{1,40}\]\s*/, "") // [Music], [Applause]
    .trim();
}

/** Lines that are only sound effects carry no knowledge. */
function isNoise(text: string): boolean {
  return !text || /^\[[^\]]*\]$/.test(text) || /^\([^)]*\)$/.test(text);
}

/**
 * A speaker tag some uploaded subtitle files carry, e.g. ">> Joe:" or "[Host]".
 * Most files have none, which is why the AI diarization pass exists.
 */
function splitSpeaker(text: string): { speaker: string; text: string } {
  const arrow = text.match(/^>>\s*([^:]{1,40}):\s*(.+)$/);
  if (arrow) return { speaker: arrow[1]!.trim(), text: arrow[2]!.trim() };
  const bracket = text.match(/^\[([^\]]{1,40})\]:?\s*(.+)$/);
  if (bracket) return { speaker: bracket[1]!.trim(), text: bracket[2]!.trim() };
  const plain = text.match(/^([A-ZА-ЯЁ][\p{L}. '-]{1,28}):\s+(.+)$/u);
  if (plain) return { speaker: plain[1]!.trim(), text: plain[2]!.trim() };
  return { speaker: "", text };
}

/** Caption events glued into readable sentence-sized lines. */
function toCues(json: Json3, startSec: number, endSec: number): Cue[] {
  const out: Cue[] = [];
  for (const event of json.events ?? []) {
    const raw = (event.segs ?? []).map((s) => s.utf8 ?? "").join("");
    const text = cleanLine(raw);
    if (isNoise(text)) continue;
    const start = (event.tStartMs ?? 0) / 1000;
    const end = start + Math.max(0.8, (event.dDurationMs ?? 2000) / 1000);
    if (end < startSec || start > endSec) continue;
    const split = splitSpeaker(text);
    const previous = out[out.length - 1];
    // Auto captions arrive in 1-3 word fragments; they only become useful once
    // glued back into whole sentences.
    if (
      previous &&
      !split.speaker &&
      previous.speaker === "Speaker" &&
      previous.end >= start - 0.6 &&
      previous.text.length < 180 &&
      !/[.!?…。？！]$/.test(previous.text)
    ) {
      previous.text = `${previous.text} ${split.text}`.trim();
      previous.end = end;
      continue;
    }
    out.push({ start: Math.max(0, start), end, text: split.text, speaker: split.speaker || "Speaker" });
  }
  return out;
}

/**
 * The timed spoken lines of a video for one time range, straight from YouTube.
 * Returns an empty list when the video has no captions at all.
 */
export async function fetchCaptionCues(
  videoId: string,
  startSec: number,
  endSec: number,
): Promise<{ cues: Cue[]; track: CaptionTrack | null }> {
  const tracks = await listCaptionTracks(videoId);
  for (const track of tracks.slice(0, 3)) {
    try {
      const url = `${track.baseUrl}${track.baseUrl.includes("fmt=") ? "" : "&fmt=json3"}`;
      const res = await fetch(url, { headers: { "User-Agent": UA } });
      if (!res.ok) continue;
      const json = (await res.json()) as Json3;
      const cues = toCues(json, startSec, endSec);
      if (cues.length) return { cues, track };
    } catch {
      // Try the next track — a single unreadable file is not a failure.
    }
  }
  return { cues: [], track: null };
}
